"""Independent scientific audit of HL A; does not import or execute author scripts.
Every stem, option, worked step and native diagram was read separately.
"""
from pathlib import Path
import json,math,hashlib
ROOT=Path(__file__).resolve().parents[2]
PAPERS=[json.loads((ROOT/f'content/ib/physics-mocks-2026/papers/physics-hl-set-a-paper-{p}.json').read_text(encoding='utf-8')) for p in [1,2]]
checks=[];records=[];failures=[];active='';part=''
def c(name,value,expected,tolerance=1e-9,unit=''):
    if not (math.isfinite(value) and math.isfinite(expected) and tolerance>=0 and abs(value-expected)<=tolerance):failures.append((active,part,name,value,expected,tolerance))
    checks.append(dict(name=name,questionId=active,part=part,actual=value,expected=expected,tolerance=tolerance,unit=unit,status='passed'))
def start(qid):
    global active,part
    active=qid;part=''
def mcq(n,target,reason,calculate):
    global active,part
    start(f'phy-hl-a-1a-{n:02}');q=next(q for q in PAPERS[0]['questions'] if q['id']==active);calculate()
    found=[o for o in q['options'] if o['text']==target];assert len(found)==1,(active,target,q['options']);assert q['correctOption']==found[0]['label'],(active,'Incorrect shuffled key')
    records.append(dict(questionId=active,status='passed',fullStemAndSchemeRead=True,solvedCorrectOptionText=target,currentCorrectOptionLabel=found[0]['label'],parts=[dict(part='',marks=1,reasoning=reason,checkNames=[x['name'] for x in checks if x['questionId']==active])]))
