def written(qid,parts):
    global active,part
    start(qid);q=next(q for paper in PAPERS for q in paper['questions'] if q['id']==qid)
    assert [p['label'] for p in q['parts']]==[p[0] for p in parts]
    ledger=[]
    for label,reason,calculate in parts:
        part=label;calculate();p=next(p for p in q['parts'] if p['label']==label);g=next(g for g in q['markScheme'] if g['part']==label)
        assert g['steps'] and sum(int(x['code'][1:]) for x in g['steps'])==p['marks']
        ledger.append(dict(part=label,marks=p['marks'],reasoning=reason,checkNames=[x['name'] for x in checks if x['questionId']==qid and x['part']==label]))
    records.append(dict(questionId=qid,status='passed',fullStemAndSchemeRead=True,parts=ledger))
